-- Quarantine the cross-species duplicates the first run missed.
--
-- The original quarantine rejected 1581 of 2289 conflicted images; 708 were
-- left verified, and preflight refused to train with 80 of them still in the
-- split. This is the same list restricted to species NOT already handled by
-- the anchovy, sturgeon and sawfish merges — 190 ids instead of 2289.
--
-- Nothing is deleted and no label is chosen; identical pixels under
-- contradictory labels are simply not trainable. Idempotent.

update training_images
   set status           = 'rejected',
       rejection_reason = 'duplicate',
       reviewed_at      = now()
